# Extracting info from three Wikipedia pages
from hermes_tools import json_parse

results = []

for url in [
    "https://en.wikipedia.org/wiki/Python_(programming_language)",
    "https://en.wikipedia.org/wiki/Rust_(programming_language)",
    "https://en.wikipedia.org/wiki/Go_(programming_language)"
]:
    new_tab(url)
    wait_for_load()

    # Get language name from title
    title = js("document.title")
    lang_name = title.split(" - ")[0].replace(" (programming language)", "")

    # Try to find "First appeared" and "Designer(s)" in infobox
    info = js("""(() => {
        const rows = document.querySelectorAll('.infobox tr');
        let first_appeared = '';
        let designer = '';

        for (const row of rows) {
            const th = row.querySelector('th');
            const td = row.querySelector('td');
            if (!th || !td) continue;

            const header = th.textContent.trim().toLowerCase();
            const value = td.textContent.trim();

            if (header.includes('first appeared')) {
                first_appeared = value;
            }
            if (header.includes('designer') || header.includes('designed by')) {
                designer = value;
            }
        }

        return { first_appeared, designer };
    })()""")

    results.append({
        "language": lang_name,
        "first_appeared": info.get("first_appeared", ""),
        "designer": info.get("designer", "")
    })
    print(f"Extracted: {lang_name}")

print("\n--- RESULTS ---")
for r in results:
    print(f"{r['language']}|{r['first_appeared']}|{r['designer']}")

