info = js("""(() => {
  const infobox = document.querySelector('.infobox');
  const rows = Array.from(infobox.querySelectorAll('tr'));

  let firstAppeared = '';
  let designedBy = '';

  for (const row of rows) {
    const cells = Array.from(row.querySelectorAll('th, td'));
    if (cells.length >= 2) {
      const label = cells[0].textContent;
      const value = cells[1].textContent.trim();

      if (label.includes('Designed')) {
        designedBy = value;
      }
      if (label.includes('First')) {
        const match = value.match(/(\\d{4})/);
        firstAppeared = match ? match[1] : value;
      }
    }
  }

  return { firstAppeared, designedBy };
})()""")
print("Rust:", info)

