# Try different selectors for the infobox image caption
result = js("(() => { 
    // Try various common Wikipedia infobox caption patterns
    const selectors = [
        '.infobox .image img',
        '.infobox-image img',
        'table.infobox img',
        '.infobox figure img'
    ];

    for (const sel of selectors) {
        const img = document.querySelector(sel);
        if (img) {
            // Look for caption in parent or sibling elements
            let parent = img.closest('td') || img.closest('figure') || img.parentElement;
            if (parent) {
                // Check for figcaption or caption text
                const figcaption = parent.querySelector('figcaption');
                if (figcaption) return figcaption.innerText.trim();

                // Check if there's text after the image in the same cell
                const nextSibling = img.parentElement.nextElementSibling;
                if (nextSibling && nextSibling.tagName === 'TD' || nextSibling?.tagName === 'DIV') {
                    return nextSibling.innerText.trim();
                }

                // Return the td text content minus the image
                return parent.innerText.trim();
            }
        }
    }
    return 'No caption found with standard selectors';
})()")
print("Caption:", result)

