# Find and extract the last item in the See also section
js("""(() => {
  // Find the See also section
  const seeAlsoHeading = Array.from(document.querySelectorAll('h2, h3')).find(h => 
    h.textContent.trim().toLowerCase() === 'see also'
  );

  if (!seeAlsoHeading) {
    return 'See also section not found';
  }

  // Get the next sibling element that contains the list
  let nextElement = seeAlsoHeading.nextElementSibling;

  // Skip any empty elements or divs until we find the ul
  while (nextElement && nextElement.tagName !== 'UL') {
    nextElement = nextElement.nextElementSibling;
  }

  if (!nextElement || nextElement.tagName !== 'UL') {
    return 'No UL found after See also heading';
  }

  // Get all list items
  const items = nextElement.querySelectorAll('li');

  if (items.length === 0) {
    return 'No items found in See also list';
  }

  // Get the last item's text
  const lastItem = items[items.length - 1];
  const link = lastItem.querySelector('a');

  if (link) {
    return link.textContent.trim();
  } else {
    return lastItem.textContent.trim();
  }
})()""")

