result = js("""(() => {
  // Try to find the See also section by ID or class
  const seeAlsoSection = document.getElementById('See_also') || 
                         document.querySelector('#See_also') ||
                         Array.from(document.querySelectorAll('span.mw-headline')).find(s => 
                           s.textContent.trim().toLowerCase() === 'see also'
                         );

  if (!seeAlsoSection) {
    return 'See also not found by common selectors';
  }

  // Get the parent section div
  let sectionDiv = seeAlsoSection.closest('div.mw-parser-output > div') || 
                   seeAlsoSection.parentElement;

  // Find all links in this section
  const links = sectionDiv ? sectionDiv.querySelectorAll('a') : [];

  // Filter to only get article links (not references, etc.)
  const articleLinks = Array.from(links).filter(a => {
    const href = a.getAttribute('href');
    return href && href.startsWith('/wiki/') && !href.includes(':');
  });

  if (articleLinks.length === 0) {
    return 'No article links found';
  }

  const lastLink = articleLinks[articleLinks.length - 1];
  return JSON.stringify({
    title: lastLink.textContent.trim(),
    href: lastLink.getAttribute('href'),
    totalLinks: articleLinks.length
  });
})()""")
print(result)

