    h.textContent.toLowerCase().includes('see also')
  );

  if (!seeAlsoHeading) return 'NOT_FOUND';

  // Get parent section
  const section = seeAlsoHeading.closest('div.mw-parser-output') || seeAlsoHeading.parentElement;

  // Find ul after the heading
  let current = seeAlsoHeading.nextElementSibling;
  while (current && current.tagName !== 'UL') {
    current = current.nextElementSibling;
  }

  if (!current || current.tagName !== 'UL') return 'NO_UL';

  const items = Array.from(current.querySelectorAll('li'));
  const titles = items.map(li => {
    const a = li.querySelector('a');
    return a ? a.textContent.trim() : li.textContent.trim();
  });

  return JSON.stringify({count: items.length, last: titles[titles.length-1], all: titles});
})()""")

