# Extracting Work section using page structure
js("""(() => {
  // Try to find the main article content area
  const mwContent = document.getElementById('mw-content-text');
  if (!mwContent) return 'No content found';

  // Find all h2 headings
  const h2s = Array.from(mwContent.querySelectorAll('h2'));
  let workSection = null;

  for (const h2 of h2s) {
    const text = h2.textContent.toLowerCase();
    if (text.includes('work') || text.includes('analytical engine')) {
      workSection = h2;
      break;
    }
  }

  if (!workSection) {
    // Return first few paragraphs as fallback
    const paragraphs = mwContent.querySelectorAll('p');
    return Array.from(paragraphs).slice(0, 5).map(p => p.textContent).join('\\n\\n---\\n\\n');
  }

  // Collect content until next h2
  let elements = [];
  let sibling = workSection.nextElementSibling;
  while (sibling && sibling.tagName !== 'H2') {
    if (sibling.tagName === 'P' || sibling.tagName === 'UL' || sibling.tagName === 'OL') {
      elements.push(sibling.textContent.trim());
    }
    sibling = sibling.nextElementSibling;
  }

  return elements.join('\\n\\n');
})()""")

