work_text = js("""(() => {
  const h2s = Array.from(document.querySelectorAll('h2'));
  let workIndex = -1;

  for (let i = 0; i < h2s.length; i++) {
    if (h2s[i].textContent.trim() === 'Work') {
      workIndex = i;
      break;
    }
  }

  if (workIndex === -1) return 'Not found';

  // Get next h2 index
  let nextIndex = workIndex + 1;
  if (nextIndex >= h2s.length) nextIndex = null;

  // Get all content between these headings
  const mwContent = document.getElementById('mw-content-text');
  if (!mwContent) return 'No mw-content-text';

  const allElements = Array.from(mwContent.children);
  let startIndex = allElements.indexOf(h2s[workIndex]);
  let endIndex = nextIndex ? allElements.indexOf(h2s[nextIndex]) : allElements.length;

  if (startIndex === -1) return 'Start not found';

  let sections = [];
  for (let i = startIndex + 1; i < endIndex && i < allElements.length; i++) {
    const el = allElements[i];
    if (el.textContent.trim()) {
      sections.push(el.textContent.trim());
    }
  }

  return sections.join('\\n\\n---\\n\\n');
})()""")

