# Find the file input by searching for it
file_input_node = None
def find_file_input(node, target_id='fileInput'):
    global file_input_node
    if node.get('backendNodeId') and node.get('attributes'):
        attrs = node['attributes']
        for i in range(0, len(attrs), 2):
            if attrs[i] == 'id' and attrs[i+1] == target_id:
                file_input_node = node
                return
    if 'children' in node:
        for child in node['children']:
            find_file_input(child, target_id)
            if file_input_node:
                return

find_file_input(cdp_result['root'])
if file_input_node:
    print(f"Found file input with backendNodeId: {file_input_node['backendNodeId']}")
else:
    print("File input not found in DOM tree")

